export const ALGORITHM_CATEGORIES = {
  ARRAYS: {
    id: 'ARRAYS', name: 'Arrays', color: '#00e5ff',
    algorithms: [
      { id: 'traversal', name: 'Traversal', recurrence: 'Visit each element once', complexity: 'O(n)', code: `function traverse(arr) {\n  for (let i = 0; i < arr.length; i++) {\n    console.log(arr[i]); // process element\n  }\n}` },
      { id: 'prefix_sum', name: 'Prefix Sum', recurrence: 'prefix[i] = prefix[i-1] + arr[i]', complexity: 'O(n) build, O(1) query', code: `function buildPrefix(arr) {\n  const prefix = [0];\n  for (let i = 0; i < arr.length; i++) {\n    prefix[i + 1] = prefix[i] + arr[i];\n  }\n  return prefix;\n}\n\nfunction rangeSum(prefix, l, r) {\n  return prefix[r + 1] - prefix[l];\n}` },
      { id: 'suffix_sum', name: 'Suffix Sum', recurrence: 'suffix[i] = suffix[i+1] + arr[i]', complexity: 'O(n)', code: `function buildSuffix(arr) {\n  const n = arr.length;\n  const suffix = new Array(n + 1).fill(0);\n  for (let i = n - 1; i >= 0; i--) {\n    suffix[i] = suffix[i + 1] + arr[i];\n  }\n  return suffix;\n}` },
      { id: 'sliding_window', name: 'Sliding Window', recurrence: 'Maintain window [l, r], expand/shrink', complexity: 'O(n)', code: `function maxSumSubarray(arr, k) {\n  let windowSum = 0;\n  for (let i = 0; i < k; i++) windowSum += arr[i];\n  let maxSum = windowSum;\n  for (let i = k; i < arr.length; i++) {\n    windowSum += arr[i] - arr[i - k];\n    maxSum = Math.max(maxSum, windowSum);\n  }\n  return maxSum;\n}` },
      { id: 'two_pointer', name: 'Two Pointer', recurrence: 'Left + Right converge in O(n)', complexity: 'O(n)', code: `function twoSum(sorted, target) {\n  let l = 0, r = sorted.length - 1;\n  while (l < r) {\n    const sum = sorted[l] + sorted[r];\n    if (sum === target) return [l, r];\n    if (sum < target) l++;\n    else r--;\n  }\n  return [];\n}` },
      { id: 'kadane', name: "Kadane's Algorithm", recurrence: 'dp[i] = max(arr[i], dp[i-1] + arr[i])', complexity: 'O(n)', code: `function maxSubarraySum(arr) {\n  let maxSum = arr[0];\n  let currentSum = arr[0];\n  for (let i = 1; i < arr.length; i++) {\n    currentSum = Math.max(arr[i], currentSum + arr[i]);\n    maxSum = Math.max(maxSum, currentSum);\n  }\n  return maxSum;\n}` },
      { id: 'dutch_flag', name: 'Dutch National Flag', recurrence: '3-way partition in O(n)', complexity: 'O(n)', code: `function dutchFlag(arr) {\n  let lo = 0, mid = 0, hi = arr.length - 1;\n  while (mid <= hi) {\n    if (arr[mid] === 0) {\n      [arr[lo], arr[mid]] = [arr[mid], arr[lo]];\n      lo++; mid++;\n    } else if (arr[mid] === 1) {\n      mid++;\n    } else {\n      [arr[mid], arr[hi]] = [arr[hi], arr[mid]];\n      hi--;\n    }\n  }\n}` },
      { id: 'merge_intervals', name: 'Merge Intervals', recurrence: 'Sort + single pass merge', complexity: 'O(n log n)', code: `function mergeIntervals(intervals) {\n  intervals.sort((a, b) => a[0] - b[0]);\n  const result = [intervals[0]];\n  for (let i = 1; i < intervals.length; i++) {\n    const last = result[result.length - 1];\n    if (intervals[i][0] <= last[1]) {\n      last[1] = Math.max(last[1], intervals[i][1]);\n    } else {\n      result.push(intervals[i]);\n    }\n  }\n  return result;\n}` },
      { id: 'next_permutation', name: 'Next Permutation', recurrence: 'Find pivot, reverse suffix', complexity: 'O(n)', code: `function nextPermutation(nums) {\n  let i = nums.length - 2;\n  while (i >= 0 && nums[i] >= nums[i + 1]) i--;\n  if (i >= 0) {\n    let j = nums.length - 1;\n    while (nums[j] <= nums[i]) j--;\n    [nums[i], nums[j]] = [nums[j], nums[i]];\n  }\n  let l = i + 1, r = nums.length - 1;\n  while (l < r) {\n    [nums[l], nums[r]] = [nums[r], nums[l]];\n    l++; r--;\n  }\n}` },
      { id: 'boyer_moore', name: 'Boyer-Moore Voting', recurrence: 'Vote cancel, then verify', complexity: 'O(n)', code: `function majorityElement(nums) {\n  let candidate = null, count = 0;\n  for (const num of nums) {\n    if (count === 0) candidate = num;\n    count += (num === candidate) ? 1 : -1;\n  }\n  return candidate;\n}` },
      { id: 'rotate_array', name: 'Rotate Array', recurrence: 'Reverse 3 times', complexity: 'O(n)', code: `function rotate(nums, k) {\n  k %= nums.length;\n  reverse(nums, 0, nums.length - 1);\n  reverse(nums, 0, k - 1);\n  reverse(nums, k, nums.length - 1);\n}\n\nfunction reverse(arr, l, r) {\n  while (l < r) {\n    [arr[l], arr[r]] = [arr[r], arr[l]];\n    l++; r--;\n  }\n}` },
      { id: 'trapping_rain', name: 'Trapping Rain Water', recurrence: 'min(maxL, maxR) - height at each index', complexity: 'O(n)', code: `function trap(height) {\n  let l = 0, r = height.length - 1;\n  let maxL = 0, maxR = 0, water = 0;\n  while (l < r) {\n    if (height[l] < height[r]) {\n      if (height[l] >= maxL) maxL = height[l];\n      else water += maxL - height[l];\n      l++;\n    } else {\n      if (height[r] >= maxR) maxR = height[r];\n      else water += maxR - height[r];\n      r--;\n    }\n  }\n  return water;\n}` },
      { id: 'stock_buy_sell', name: 'Stock Buy and Sell', recurrence: 'Track min price, max profit', complexity: 'O(n)', code: `function maxProfit(prices) {\n  let minPrice = Infinity;\n  let maxProfit = 0;\n  for (const price of prices) {\n    if (price < minPrice) {\n      minPrice = price;\n    } else {\n      maxProfit = Math.max(maxProfit, price - minPrice);\n    }\n  }\n  return maxProfit;\n}` },
      { id: 'max_product_subarray', name: 'Maximum Product Subarray', recurrence: 'Track max and min at each step', complexity: 'O(n)', code: `function maxProduct(nums) {\n  let maxProd = nums[0];\n  let minProd = nums[0];\n  let result = nums[0];\n  for (let i = 1; i < nums.length; i++) {\n    const temp = maxProd;\n    maxProd = Math.max(nums[i], maxProd * nums[i], minProd * nums[i]);\n    minProd = Math.min(nums[i], temp * nums[i], minProd * nums[i]);\n    result = Math.max(result, maxProd);\n  }\n  return result;\n}` },
      { id: 'subarray_sum', name: 'Subarray Sum Problems', recurrence: 'Prefix sum + hash map', complexity: 'O(n)', code: `function subarraySum(nums, k) {\n  const map = new Map([[0, 1]]);\n  let count = 0, prefix = 0;\n  for (const num of nums) {\n    prefix += num;\n    count += (map.get(prefix - k) || 0);\n    map.set(prefix, (map.get(prefix) || 0) + 1);\n  }\n  return count;\n}` },
    ]
  },

  SEARCHING: {
    id: 'SEARCHING', name: 'Searching', color: '#40c4ff',
    algorithms: [
      { id: 'linear_search', name: 'Linear Search', recurrence: 'Scan each element', complexity: 'O(n)', code: `function linearSearch(arr, target) {\n  for (let i = 0; i < arr.length; i++) {\n    if (arr[i] === target) return i;\n  }\n  return -1;\n}` },
      { id: 'binary_search', name: 'Binary Search', recurrence: 'T(n) = T(n/2) + O(1)', complexity: 'O(log n)', code: `function binarySearch(arr, target) {\n  let left = 0, right = arr.length - 1;\n  while (left <= right) {\n    const mid = Math.floor((left + right) / 2);\n    if (arr[mid] === target) return mid;\n    if (arr[mid] < target) left = mid + 1;\n    else right = mid - 1;\n  }\n  return -1;\n}` },
      { id: 'lower_upper_bound', name: 'Lower / Upper Bound', recurrence: 'Binary search variant', complexity: 'O(log n)', code: `function lowerBound(arr, target) {\n  let lo = 0, hi = arr.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (arr[mid] < target) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;\n}\n\nfunction upperBound(arr, target) {\n  let lo = 0, hi = arr.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (arr[mid] <= target) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;\n}` },
      { id: 'search_rotated', name: 'Search in Rotated Array', recurrence: 'Binary search with rotation check', complexity: 'O(log n)', code: `function searchRotated(nums, target) {\n  let l = 0, r = nums.length - 1;\n  while (l <= r) {\n    const mid = (l + r) >> 1;\n    if (nums[mid] === target) return mid;\n    if (nums[l] <= nums[mid]) {\n      if (nums[l] <= target && target < nums[mid]) r = mid - 1;\n      else l = mid + 1;\n    } else {\n      if (nums[mid] < target && target <= nums[r]) l = mid + 1;\n      else r = mid - 1;\n    }\n  }\n  return -1;\n}` },
      { id: 'search_2d', name: 'Search in 2D Matrix', recurrence: 'Binary search on flattened matrix', complexity: 'O(log(m*n))', code: `function searchMatrix(matrix, target) {\n  const m = matrix.length, n = matrix[0].length;\n  let lo = 0, hi = m * n - 1;\n  while (lo <= hi) {\n    const mid = (lo + hi) >> 1;\n    const val = matrix[Math.floor(mid / n)][mid % n];\n    if (val === target) return true;\n    if (val < target) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return false;\n}` },
      { id: 'peak_element', name: 'Peak Element', recurrence: 'Binary search on slope', complexity: 'O(log n)', code: `function findPeakElement(nums) {\n  let l = 0, r = nums.length - 1;\n  while (l < r) {\n    const mid = (l + r) >> 1;\n    if (nums[mid] > nums[mid + 1]) r = mid;\n    else l = mid + 1;\n  }\n  return l;\n}` },
      { id: 'kth_missing', name: 'Kth Missing Number', recurrence: 'Binary search on missing count', complexity: 'O(log n)', code: `function findKthPositive(arr, k) {\n  let lo = 0, hi = arr.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (arr[mid] - (mid + 1) >= k) hi = mid;\n    else lo = mid + 1;\n  }\n  return lo + k;\n}` },
    ]
  },

  SORTING: {
    id: 'SORTING', name: 'Sorting', color: '#00ffff',
    algorithms: [
      { id: 'bubble_sort', name: 'Bubble Sort', recurrence: 'T(n) = T(n-1) + O(n)', complexity: 'O(n²)', code: `function bubbleSort(arr) {\n  const n = arr.length;\n  for (let i = 0; i < n - 1; i++) {\n    for (let j = 0; j < n - i - 1; j++) {\n      if (arr[j] > arr[j + 1]) {\n        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];\n      }\n    }\n  }\n  return arr;\n}` },
      { id: 'selection_sort', name: 'Selection Sort', recurrence: 'Find min in O(n), repeat n times', complexity: 'O(n²)', code: `function selectionSort(arr) {\n  for (let i = 0; i < arr.length; i++) {\n    let minIdx = i;\n    for (let j = i + 1; j < arr.length; j++) {\n      if (arr[j] < arr[minIdx]) minIdx = j;\n    }\n    [arr[i], arr[minIdx]] = [arr[minIdx], arr[i]];\n  }\n  return arr;\n}` },
      { id: 'insertion_sort', name: 'Insertion Sort', recurrence: 'T(n) = T(n-1) + O(n)', complexity: 'O(n²)', code: `function insertionSort(arr) {\n  for (let i = 1; i < arr.length; i++) {\n    const key = arr[i];\n    let j = i - 1;\n    while (j >= 0 && arr[j] > key) {\n      arr[j + 1] = arr[j];\n      j--;\n    }\n    arr[j + 1] = key;\n  }\n  return arr;\n}` },
      { id: 'merge_sort', name: 'Merge Sort', recurrence: 'T(n) = 2T(n/2) + O(n)', complexity: 'O(n log n)', code: `function mergeSort(arr) {\n  if (arr.length <= 1) return arr;\n  const mid = arr.length >> 1;\n  const left = mergeSort(arr.slice(0, mid));\n  const right = mergeSort(arr.slice(mid));\n  return merge(left, right);\n}\n\nfunction merge(l, r) {\n  const res = [];\n  let i = 0, j = 0;\n  while (i < l.length && j < r.length) {\n    if (l[i] <= r[j]) res.push(l[i++]);\n    else res.push(r[j++]);\n  }\n  return res.concat(l.slice(i), r.slice(j));\n}` },
      { id: 'quick_sort', name: 'Quick Sort', recurrence: 'Avg: T(n)=2T(n/2)+O(n), Worst: T(n-1)+O(n)', complexity: 'O(n log n) avg', code: `function quickSort(arr, lo = 0, hi = arr.length - 1) {\n  if (lo < hi) {\n    const p = partition(arr, lo, hi);\n    quickSort(arr, lo, p - 1);\n    quickSort(arr, p + 1, hi);\n  }\n  return arr;\n}\n\nfunction partition(arr, lo, hi) {\n  const pivot = arr[hi];\n  let i = lo - 1;\n  for (let j = lo; j < hi; j++) {\n    if (arr[j] <= pivot) {\n      i++;\n      [arr[i], arr[j]] = [arr[j], arr[i]];\n    }\n  }\n  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];\n  return i + 1;\n}` },
      { id: 'heap_sort', name: 'Heap Sort', recurrence: 'Build heap O(n) + n extractions O(log n)', complexity: 'O(n log n)', code: `function heapSort(arr) {\n  const n = arr.length;\n  for (let i = Math.floor(n / 2) - 1; i >= 0; i--)\n    heapify(arr, n, i);\n  for (let i = n - 1; i > 0; i--) {\n    [arr[0], arr[i]] = [arr[i], arr[0]];\n    heapify(arr, i, 0);\n  }\n  return arr;\n}\n\nfunction heapify(arr, n, i) {\n  let largest = i;\n  const l = 2 * i + 1, r = 2 * i + 2;\n  if (l < n && arr[l] > arr[largest]) largest = l;\n  if (r < n && arr[r] > arr[largest]) largest = r;\n  if (largest !== i) {\n    [arr[i], arr[largest]] = [arr[largest], arr[i]];\n    heapify(arr, n, largest);\n  }\n}` },
      { id: 'counting_sort', name: 'Counting Sort', recurrence: 'O(n + k) where k is max value', complexity: 'O(n + k)', code: `function countingSort(arr) {\n  const max = Math.max(...arr);\n  const count = new Array(max + 1).fill(0);\n  for (const num of arr) count[num]++;\n  const result = [];\n  for (let i = 0; i <= max; i++) {\n    while (count[i]-- > 0) result.push(i);\n  }\n  return result;\n}` },
      { id: 'radix_sort', name: 'Radix Sort', recurrence: 'O(d * (n + k)) d=digits k=base', complexity: 'O(d * n)', code: `function radixSort(arr) {\n  const max = Math.max(...arr);\n  for (let exp = 1; Math.floor(max / exp) > 0; exp *= 10) {\n    countingSortByDigit(arr, exp);\n  }\n  return arr;\n}\n\nfunction countingSortByDigit(arr, exp) {\n  const output = new Array(arr.length).fill(0);\n  const count = new Array(10).fill(0);\n  for (const num of arr) count[Math.floor(num / exp) % 10]++;\n  for (let i = 1; i < 10; i++) count[i] += count[i - 1];\n  for (let i = arr.length - 1; i >= 0; i--) {\n    const idx = Math.floor(arr[i] / exp) % 10;\n    output[--count[idx]] = arr[i];\n  }\n  for (let i = 0; i < arr.length; i++) arr[i] = output[i];\n}` },
      { id: 'bucket_sort', name: 'Bucket Sort', recurrence: 'Distribute to buckets + sort each', complexity: 'O(n + k) avg', code: `function bucketSort(arr) {\n  const n = arr.length;\n  const max = Math.max(...arr);\n  const buckets = Array.from({ length: n }, () => []);\n  for (const num of arr) {\n    const idx = Math.floor((num / (max + 1)) * n);\n    buckets[idx].push(num);\n  }\n  return buckets.flatMap(b => b.sort((a, c) => a - c));\n}` },
      { id: 'quick_select', name: 'Quick Select', recurrence: 'Avg T(n) = T(n/2) + O(n)', complexity: 'O(n) avg', code: `function quickSelect(arr, k) {\n  return select(arr, 0, arr.length - 1, k - 1);\n}\n\nfunction select(arr, lo, hi, k) {\n  if (lo === hi) return arr[lo];\n  const pivot = partition(arr, lo, hi);\n  if (pivot === k) return arr[pivot];\n  if (pivot < k) return select(arr, pivot + 1, hi, k);\n  return select(arr, lo, pivot - 1, k);\n}\n\nfunction partition(arr, lo, hi) {\n  const p = arr[hi];\n  let i = lo - 1;\n  for (let j = lo; j < hi; j++) {\n    if (arr[j] <= p) { i++; [arr[i], arr[j]] = [arr[j], arr[i]]; }\n  }\n  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];\n  return i + 1;\n}` },
    ]
  },

  STRINGS: {
    id: 'STRINGS', name: 'Strings', color: '#ea80fc',
    algorithms: [
      { id: 'reverse_string', name: 'Reverse String', recurrence: 'Two pointer O(n)', complexity: 'O(n)', code: `function reverseString(s) {\n  let l = 0, r = s.length - 1;\n  const arr = s.split('');\n  while (l < r) {\n    [arr[l], arr[r]] = [arr[r], arr[l]];\n    l++; r--;\n  }\n  return arr.join('');\n}` },
      { id: 'palindrome_check', name: 'Palindrome Check', recurrence: 'Two pointer O(n)', complexity: 'O(n)', code: `function isPalindrome(s) {\n  const clean = s.toLowerCase().replace(/[^a-z0-9]/g, '');\n  let l = 0, r = clean.length - 1;\n  while (l < r) {\n    if (clean[l] !== clean[r]) return false;\n    l++; r--;\n  }\n  return true;\n}` },
      { id: 'anagram_check', name: 'Anagram Check', recurrence: 'Frequency count O(n)', complexity: 'O(n)', code: `function isAnagram(s, t) {\n  if (s.length !== t.length) return false;\n  const count = {};\n  for (const c of s) count[c] = (count[c] || 0) + 1;\n  for (const c of t) {\n    if (!count[c]) return false;\n    count[c]--;\n  }\n  return true;\n}` },
      { id: 'longest_common_prefix', name: 'Longest Common Prefix', recurrence: 'Vertical scan O(n*m)', complexity: 'O(n*m)', code: `function longestCommonPrefix(strs) {\n  if (!strs.length) return '';\n  let prefix = strs[0];\n  for (let i = 1; i < strs.length; i++) {\n    while (!strs[i].startsWith(prefix)) {\n      prefix = prefix.slice(0, -1);\n      if (!prefix) return '';\n    }\n  }\n  return prefix;\n}` },
      { id: 'sliding_window_str', name: 'Sliding Window on Strings', recurrence: 'Expand / shrink window O(n)', complexity: 'O(n)', code: `function lengthOfLongestSubstring(s) {\n  const map = new Map();\n  let maxLen = 0, l = 0;\n  for (let r = 0; r < s.length; r++) {\n    if (map.has(s[r])) l = Math.max(l, map.get(s[r]) + 1);\n    map.set(s[r], r);\n    maxLen = Math.max(maxLen, r - l + 1);\n  }\n  return maxLen;\n}` },
      { id: 'kmp', name: 'KMP Algorithm', recurrence: 'Build LPS O(m) + search O(n)', complexity: 'O(n + m)', code: `function kmpSearch(text, pattern) {\n  const lps = buildLPS(pattern);\n  const results = [];\n  let i = 0, j = 0;\n  while (i < text.length) {\n    if (text[i] === pattern[j]) { i++; j++; }\n    if (j === pattern.length) {\n      results.push(i - j);\n      j = lps[j - 1];\n    } else if (i < text.length && text[i] !== pattern[j]) {\n      if (j !== 0) j = lps[j - 1];\n      else i++;\n    }\n  }\n  return results;\n}\n\nfunction buildLPS(p) {\n  const lps = [0];\n  let len = 0, i = 1;\n  while (i < p.length) {\n    if (p[i] === p[len]) { lps[i++] = ++len; }\n    else if (len) { len = lps[len - 1]; }\n    else { lps[i++] = 0; }\n  }\n  return lps;\n}` },
      { id: 'rabin_karp', name: 'Rabin-Karp Algorithm', recurrence: 'Rolling hash O(n+m) avg', complexity: 'O(n + m)', code: `function rabinKarp(text, pattern) {\n  const BASE = 31, MOD = 1e9 + 9;\n  const n = text.length, m = pattern.length;\n  const results = [];\n  let ph = 0, th = 0, power = 1;\n  for (let i = 0; i < m - 1; i++) power = (power * BASE) % MOD;\n  for (let i = 0; i < m; i++) {\n    ph = (ph * BASE + pattern.charCodeAt(i)) % MOD;\n    th = (th * BASE + text.charCodeAt(i)) % MOD;\n  }\n  for (let i = 0; i <= n - m; i++) {\n    if (ph === th && text.slice(i, i + m) === pattern) results.push(i);\n    if (i < n - m) {\n      th = (BASE * (th - text.charCodeAt(i) * power) + text.charCodeAt(i + m)) % MOD;\n      if (th < 0) th += MOD;\n    }\n  }\n  return results;\n}` },
      { id: 'z_algorithm', name: 'Z Algorithm', recurrence: 'Z[i] = length of longest match starting at i', complexity: 'O(n)', code: `function zAlgorithm(s) {\n  const n = s.length;\n  const z = new Array(n).fill(0);\n  let l = 0, r = 0;\n  for (let i = 1; i < n; i++) {\n    if (i < r) z[i] = Math.min(r - i, z[i - l]);\n    while (i + z[i] < n && s[z[i]] === s[i + z[i]]) z[i]++;\n    if (i + z[i] > r) { l = i; r = i + z[i]; }\n  }\n  return z;\n}` },
      { id: 'manacher', name: "Manacher's Algorithm", recurrence: 'Expand around center with mirror', complexity: 'O(n)', code: `function manacher(s) {\n  const t = '#' + s.split('').join('#') + '#';\n  const n = t.length;\n  const p = new Array(n).fill(0);\n  let c = 0, r = 0;\n  for (let i = 0; i < n; i++) {\n    if (i < r) p[i] = Math.min(r - i, p[2 * c - i]);\n    while (i + p[i] + 1 < n && i - p[i] - 1 >= 0 && t[i + p[i] + 1] === t[i - p[i] - 1]) p[i]++;\n    if (i + p[i] > r) { c = i; r = i + p[i]; }\n  }\n  return p;\n}` },
      { id: 'min_window_substr', name: 'Minimum Window Substring', recurrence: 'Sliding window + frequency map', complexity: 'O(n)', code: `function minWindow(s, t) {\n  const need = {}, have = {};\n  for (const c of t) need[c] = (need[c] || 0) + 1;\n  let formed = 0, required = Object.keys(need).length;\n  let l = 0, minLen = Infinity, res = '';\n  for (let r = 0; r < s.length; r++) {\n    have[s[r]] = (have[s[r]] || 0) + 1;\n    if (need[s[r]] && have[s[r]] === need[s[r]]) formed++;\n    while (formed === required) {\n      if (r - l + 1 < minLen) { minLen = r - l + 1; res = s.slice(l, r + 1); }\n      have[s[l]]--;\n      if (need[s[l]] && have[s[l]] < need[s[l]]) formed--;\n      l++;\n    }\n  }\n  return res;\n}` },
    ]
  },

  LINKED_LIST: {
    id: 'LINKED_LIST', name: 'Linked List', color: '#ff80ab',
    algorithms: [
      { id: 'll_reverse', name: 'Reverse Linked List', recurrence: 'Iterative O(n)', complexity: 'O(n)', code: `function reverse(head) {\n  let prev = null, curr = head;\n  while (curr) {\n    const next = curr.next;\n    curr.next = prev;\n    prev = curr;\n    curr = next;\n  }\n  return prev;\n}` },
      { id: 'll_cycle', name: 'Detect Cycle (Floyd)', recurrence: 'Fast/slow pointers meet in cycle', complexity: 'O(n)', code: `function hasCycle(head) {\n  let slow = head, fast = head;\n  while (fast && fast.next) {\n    slow = slow.next;\n    fast = fast.next.next;\n    if (slow === fast) return true;\n  }\n  return false;\n}` },
      { id: 'll_middle', name: 'Find Middle Node', recurrence: 'Fast/slow pointer', complexity: 'O(n)', code: `function findMiddle(head) {\n  let slow = head, fast = head;\n  while (fast && fast.next) {\n    slow = slow.next;\n    fast = fast.next.next;\n  }\n  return slow;\n}` },
      { id: 'll_merge_sorted', name: 'Merge Two Sorted Lists', recurrence: 'Compare and link O(n+m)', complexity: 'O(n + m)', code: `function mergeTwoLists(l1, l2) {\n  const dummy = { next: null };\n  let cur = dummy;\n  while (l1 && l2) {\n    if (l1.val <= l2.val) { cur.next = l1; l1 = l1.next; }\n    else { cur.next = l2; l2 = l2.next; }\n    cur = cur.next;\n  }\n  cur.next = l1 || l2;\n  return dummy.next;\n}` },
      { id: 'll_remove_nth', name: 'Remove Nth Node', recurrence: 'Two pointer with gap of n', complexity: 'O(n)', code: `function removeNthFromEnd(head, n) {\n  const dummy = { next: head };\n  let fast = dummy, slow = dummy;\n  for (let i = 0; i <= n; i++) fast = fast.next;\n  while (fast) { fast = fast.next; slow = slow.next; }\n  slow.next = slow.next.next;\n  return dummy.next;\n}` },
      { id: 'll_intersection', name: 'Intersection Point', recurrence: 'Two pointer switch', complexity: 'O(n + m)', code: `function getIntersectionNode(headA, headB) {\n  let a = headA, b = headB;\n  while (a !== b) {\n    a = a ? a.next : headB;\n    b = b ? b.next : headA;\n  }\n  return a;\n}` },
      { id: 'll_reverse_k', name: 'Reverse in K Groups', recurrence: 'Reverse k nodes + recurse', complexity: 'O(n)', code: `function reverseKGroup(head, k) {\n  let node = head;\n  for (let i = 0; i < k; i++) {\n    if (!node) return head;\n    node = node.next;\n  }\n  let prev = null, curr = head;\n  for (let i = 0; i < k; i++) {\n    const next = curr.next;\n    curr.next = prev;\n    prev = curr;\n    curr = next;\n  }\n  head.next = reverseKGroup(node, k);\n  return prev;\n}` },
      { id: 'll_lru', name: 'LRU Cache', recurrence: 'HashMap + Doubly Linked List', complexity: 'O(1) get/put', code: `class LRUCache {\n  constructor(capacity) {\n    this.cap = capacity;\n    this.map = new Map();\n  }\n  get(key) {\n    if (!this.map.has(key)) return -1;\n    const val = this.map.get(key);\n    this.map.delete(key);\n    this.map.set(key, val);\n    return val;\n  }\n  put(key, value) {\n    this.map.delete(key);\n    this.map.set(key, value);\n    if (this.map.size > this.cap)\n      this.map.delete(this.map.keys().next().value);\n  }\n}` },
    ]
  },

  STACK: {
    id: 'STACK', name: 'Stack', color: '#ff9100',
    algorithms: [
      { id: 'next_greater', name: 'Next Greater Element', recurrence: 'Monotonic stack O(n)', complexity: 'O(n)', code: `function nextGreaterElement(nums) {\n  const res = new Array(nums.length).fill(-1);\n  const stack = [];\n  for (let i = 0; i < nums.length; i++) {\n    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) {\n      res[stack.pop()] = nums[i];\n    }\n    stack.push(i);\n  }\n  return res;\n}` },
      { id: 'prev_greater', name: 'Previous Greater Element', recurrence: 'Monotonic stack O(n)', complexity: 'O(n)', code: `function previousGreater(nums) {\n  const res = new Array(nums.length).fill(-1);\n  const stack = [];\n  for (let i = 0; i < nums.length; i++) {\n    while (stack.length && stack[stack.length - 1] <= nums[i])\n      stack.pop();\n    if (stack.length) res[i] = stack[stack.length - 1];\n    stack.push(nums[i]);\n  }\n  return res;\n}` },
      { id: 'valid_parens', name: 'Valid Parentheses', recurrence: 'Stack match O(n)', complexity: 'O(n)', code: `function isValid(s) {\n  const stack = [];\n  const map = { ')': '(', '}': '{', ']': '[' };\n  for (const c of s) {\n    if ('([{'.includes(c)) stack.push(c);\n    else if (stack.pop() !== map[c]) return false;\n  }\n  return stack.length === 0;\n}` },
      { id: 'largest_rectangle', name: 'Largest Rectangle in Histogram', recurrence: 'Monotonic stack O(n)', complexity: 'O(n)', code: `function largestRectangleArea(heights) {\n  const stack = [];\n  let maxArea = 0;\n  heights.push(0);\n  for (let i = 0; i < heights.length; i++) {\n    while (stack.length && heights[stack[stack.length - 1]] > heights[i]) {\n      const h = heights[stack.pop()];\n      const w = stack.length ? i - stack[stack.length - 1] - 1 : i;\n      maxArea = Math.max(maxArea, h * w);\n    }\n    stack.push(i);\n  }\n  return maxArea;\n}` },
      { id: 'min_stack', name: 'Min Stack', recurrence: 'Pair stack O(1) getMin', complexity: 'O(1) all ops', code: `class MinStack {\n  constructor() { this.stack = []; }\n  push(val) {\n    const min = this.stack.length ? Math.min(this.getMin(), val) : val;\n    this.stack.push([val, min]);\n  }\n  pop() { this.stack.pop(); }\n  top() { return this.stack[this.stack.length - 1][0]; }\n  getMin() { return this.stack[this.stack.length - 1][1]; }\n}` },
      { id: 'infix_postfix', name: 'Infix to Postfix', recurrence: 'Operator precedence via stack', complexity: 'O(n)', code: `function infixToPostfix(expr) {\n  const prec = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };\n  const stack = [], output = [];\n  for (const c of expr) {\n    if (/\\w/.test(c)) { output.push(c); }\n    else if (c === '(') { stack.push(c); }\n    else if (c === ')') {\n      while (stack[stack.length - 1] !== '(') output.push(stack.pop());\n      stack.pop();\n    } else {\n      while (stack.length && prec[stack[stack.length - 1]] >= prec[c])\n        output.push(stack.pop());\n      stack.push(c);\n    }\n  }\n  return output.concat(stack.reverse()).join(' ');\n}` },
    ]
  },

  QUEUE: {
    id: 'QUEUE', name: 'Queue', color: '#ffff00',
    algorithms: [
      { id: 'queue_using_stack', name: 'Queue using Stack', recurrence: 'Amortized O(1) enqueue/dequeue', complexity: 'O(1) amortized', code: `class MyQueue {\n  constructor() { this.in = []; this.out = []; }\n  push(x) { this.in.push(x); }\n  pop() {\n    if (!this.out.length) while (this.in.length) this.out.push(this.in.pop());\n    return this.out.pop();\n  }\n  peek() {\n    if (!this.out.length) while (this.in.length) this.out.push(this.in.pop());\n    return this.out[this.out.length - 1];\n  }\n}` },
      { id: 'stack_using_queue', name: 'Stack using Queue', recurrence: 'Rotate queue on push O(n)', complexity: 'O(n) push', code: `class MyStack {\n  constructor() { this.queue = []; }\n  push(x) {\n    this.queue.push(x);\n    for (let i = 0; i < this.queue.length - 1; i++)\n      this.queue.push(this.queue.shift());\n  }\n  pop() { return this.queue.shift(); }\n  top() { return this.queue[0]; }\n}` },
      { id: 'sliding_window_max', name: 'Sliding Window Maximum', recurrence: 'Deque maintains max descending O(n)', complexity: 'O(n)', code: `function maxSlidingWindow(nums, k) {\n  const deque = [], result = [];\n  for (let i = 0; i < nums.length; i++) {\n    while (deque.length && deque[0] < i - k + 1) deque.shift();\n    while (deque.length && nums[deque[deque.length - 1]] < nums[i]) deque.pop();\n    deque.push(i);\n    if (i >= k - 1) result.push(nums[deque[0]]);\n  }\n  return result;\n}` },
      { id: 'circular_queue', name: 'Circular Queue', recurrence: 'Modular indexing O(1)', complexity: 'O(1)', code: `class CircularQueue {\n  constructor(k) { this.data = new Array(k); this.head = -1; this.tail = -1; this.size = k; }\n  enQueue(val) {\n    if (this.isFull()) return false;\n    if (this.isEmpty()) this.head = 0;\n    this.tail = (this.tail + 1) % this.size;\n    this.data[this.tail] = val;\n    return true;\n  }\n  deQueue() {\n    if (this.isEmpty()) return false;\n    if (this.head === this.tail) { this.head = -1; this.tail = -1; }\n    else this.head = (this.head + 1) % this.size;\n    return true;\n  }\n  isFull() { return (this.tail + 1) % this.size === this.head; }\n  isEmpty() { return this.head === -1; }\n}` },
    ]
  },

  HASHING: {
    id: 'HASHING', name: 'Hashing', color: '#76ff03',
    algorithms: [
      { id: 'freq_count', name: 'Frequency Count', recurrence: 'Single pass O(n)', complexity: 'O(n)', code: `function frequencyCount(arr) {\n  const freq = {};\n  for (const num of arr) {\n    freq[num] = (freq[num] || 0) + 1;\n  }\n  return freq;\n}` },
      { id: 'two_sum_hash', name: 'Two Sum', recurrence: 'Hash map complement O(n)', complexity: 'O(n)', code: `function twoSum(nums, target) {\n  const map = new Map();\n  for (let i = 0; i < nums.length; i++) {\n    const complement = target - nums[i];\n    if (map.has(complement)) return [map.get(complement), i];\n    map.set(nums[i], i);\n  }\n  return [];\n}` },
      { id: 'subarray_sum_k', name: 'Subarray Sum Equals K', recurrence: 'Prefix sum + hash O(n)', complexity: 'O(n)', code: `function subarraySum(nums, k) {\n  const map = new Map([[0, 1]]);\n  let count = 0, sum = 0;\n  for (const num of nums) {\n    sum += num;\n    count += (map.get(sum - k) || 0);\n    map.set(sum, (map.get(sum) || 0) + 1);\n  }\n  return count;\n}` },
      { id: 'longest_consecutive', name: 'Longest Consecutive Sequence', recurrence: 'Hash set, start from chain root O(n)', complexity: 'O(n)', code: `function longestConsecutive(nums) {\n  const set = new Set(nums);\n  let maxLen = 0;\n  for (const num of set) {\n    if (!set.has(num - 1)) {\n      let curr = num, len = 1;\n      while (set.has(curr + 1)) { curr++; len++; }\n      maxLen = Math.max(maxLen, len);\n    }\n  }\n  return maxLen;\n}` },
      { id: 'group_anagrams', name: 'Group Anagrams', recurrence: 'Sort key or count key O(n*k)', complexity: 'O(n * k log k)', code: `function groupAnagrams(strs) {\n  const map = new Map();\n  for (const s of strs) {\n    const key = s.split('').sort().join('');\n    if (!map.has(key)) map.set(key, []);\n    map.get(key).push(s);\n  }\n  return [...map.values()];\n}` },
    ]
  },

  TREES: {
    id: 'TREES', name: 'Trees', color: '#69f0ae',
    algorithms: [
      { id: 'tree_dfs', name: 'DFS', recurrence: 'T(n) = O(n)', complexity: 'O(n)', code: `function dfs(root) {\n  if (!root) return;\n  console.log(root.val); // process\n  dfs(root.left);\n  dfs(root.right);\n}` },
      { id: 'tree_bfs', name: 'BFS', recurrence: 'Level by level O(n)', complexity: 'O(n)', code: `function bfs(root) {\n  if (!root) return;\n  const queue = [root];\n  while (queue.length) {\n    const node = queue.shift();\n    console.log(node.val);\n    if (node.left) queue.push(node.left);\n    if (node.right) queue.push(node.right);\n  }\n}` },
      { id: 'inorder', name: 'Inorder Traversal', recurrence: 'Left → Root → Right', complexity: 'O(n)', code: `function inorder(root) {\n  const result = [];\n  function traverse(node) {\n    if (!node) return;\n    traverse(node.left);\n    result.push(node.val);\n    traverse(node.right);\n  }\n  traverse(root);\n  return result;\n}` },
      { id: 'preorder', name: 'Preorder Traversal', recurrence: 'Root → Left → Right', complexity: 'O(n)', code: `function preorder(root) {\n  const result = [];\n  function traverse(node) {\n    if (!node) return;\n    result.push(node.val);\n    traverse(node.left);\n    traverse(node.right);\n  }\n  traverse(root);\n  return result;\n}` },
      { id: 'postorder', name: 'Postorder Traversal', recurrence: 'Left → Right → Root', complexity: 'O(n)', code: `function postorder(root) {\n  const result = [];\n  function traverse(node) {\n    if (!node) return;\n    traverse(node.left);\n    traverse(node.right);\n    result.push(node.val);\n  }\n  traverse(root);\n  return result;\n}` },
      { id: 'level_order', name: 'Level Order Traversal', recurrence: 'BFS layer by layer', complexity: 'O(n)', code: `function levelOrder(root) {\n  const result = [];\n  if (!root) return result;\n  const queue = [root];\n  while (queue.length) {\n    const level = [];\n    const len = queue.length;\n    for (let i = 0; i < len; i++) {\n      const node = queue.shift();\n      level.push(node.val);\n      if (node.left) queue.push(node.left);\n      if (node.right) queue.push(node.right);\n    }\n    result.push(level);\n  }\n  return result;\n}` },
      { id: 'diameter', name: 'Diameter of Tree', recurrence: 'Max(left depth + right depth) at each node', complexity: 'O(n)', code: `function diameterOfBinaryTree(root) {\n  let maxDiam = 0;\n  function depth(node) {\n    if (!node) return 0;\n    const l = depth(node.left);\n    const r = depth(node.right);\n    maxDiam = Math.max(maxDiam, l + r);\n    return 1 + Math.max(l, r);\n  }\n  depth(root);\n  return maxDiam;\n}` },
      { id: 'lca', name: 'Lowest Common Ancestor', recurrence: 'DFS, return node when found', complexity: 'O(n)', code: `function lowestCommonAncestor(root, p, q) {\n  if (!root || root === p || root === q) return root;\n  const left = lowestCommonAncestor(root.left, p, q);\n  const right = lowestCommonAncestor(root.right, p, q);\n  if (left && right) return root;\n  return left || right;\n}` },
      { id: 'max_path_sum', name: 'Maximum Path Sum', recurrence: 'Max gain from each subtree', complexity: 'O(n)', code: `function maxPathSum(root) {\n  let max = -Infinity;\n  function gain(node) {\n    if (!node) return 0;\n    const l = Math.max(gain(node.left), 0);\n    const r = Math.max(gain(node.right), 0);\n    max = Math.max(max, node.val + l + r);\n    return node.val + Math.max(l, r);\n  }\n  gain(root);\n  return max;\n}` },
    ]
  },

  BST: {
    id: 'BST', name: 'BST', color: '#00e5ff',
    algorithms: [
      { id: 'bst_insert', name: 'Insert / Delete / Search', recurrence: 'O(h) where h=height', complexity: 'O(log n) avg', code: `function insertBST(root, val) {\n  if (!root) return { val, left: null, right: null };\n  if (val < root.val) root.left = insertBST(root.left, val);\n  else root.right = insertBST(root.right, val);\n  return root;\n}\n\nfunction searchBST(root, val) {\n  if (!root || root.val === val) return root;\n  if (val < root.val) return searchBST(root.left, val);\n  return searchBST(root.right, val);\n}` },
      { id: 'validate_bst', name: 'Validate BST', recurrence: 'DFS with range [min, max]', complexity: 'O(n)', code: `function isValidBST(root, min = -Infinity, max = Infinity) {\n  if (!root) return true;\n  if (root.val <= min || root.val >= max) return false;\n  return isValidBST(root.left, min, root.val) &&\n         isValidBST(root.right, root.val, max);\n}` },
      { id: 'kth_smallest', name: 'Kth Smallest Element', recurrence: 'Inorder traversal stop at k', complexity: 'O(n)', code: `function kthSmallest(root, k) {\n  let count = 0, result = 0;\n  function inorder(node) {\n    if (!node) return;\n    inorder(node.left);\n    if (++count === k) { result = node.val; return; }\n    inorder(node.right);\n  }\n  inorder(root);\n  return result;\n}` },
      { id: 'inorder_successor', name: 'Inorder Successor', recurrence: 'Go right, then leftmost', complexity: 'O(h)', code: `function inorderSuccessor(root, p) {\n  let successor = null;\n  while (root) {\n    if (p.val < root.val) {\n      successor = root;\n      root = root.left;\n    } else {\n      root = root.right;\n    }\n  }\n  return successor;\n}` },
    ]
  },

  HEAPS: {
    id: 'HEAPS', name: 'Heaps', color: '#ffd740',
    algorithms: [
      { id: 'heapify', name: 'Heapify', recurrence: 'O(n) build, O(log n) per op', complexity: 'O(n)', code: `function heapify(arr, n, i) {\n  let largest = i;\n  const l = 2 * i + 1, r = 2 * i + 2;\n  if (l < n && arr[l] > arr[largest]) largest = l;\n  if (r < n && arr[r] > arr[largest]) largest = r;\n  if (largest !== i) {\n    [arr[i], arr[largest]] = [arr[largest], arr[i]];\n    heapify(arr, n, largest);\n  }\n}\n\nfunction buildHeap(arr) {\n  for (let i = Math.floor(arr.length / 2) - 1; i >= 0; i--)\n    heapify(arr, arr.length, i);\n}` },
      { id: 'kth_largest', name: 'Kth Largest Element', recurrence: 'Min heap of size k', complexity: 'O(n log k)', code: `class MinHeap {\n  constructor() { this.heap = []; }\n  push(val) { this.heap.push(val); this.heap.sort((a,b)=>a-b); }\n  pop() { return this.heap.shift(); }\n  peek() { return this.heap[0]; }\n  size() { return this.heap.length; }\n}\n\nfunction findKthLargest(nums, k) {\n  const heap = new MinHeap();\n  for (const num of nums) {\n    heap.push(num);\n    if (heap.size() > k) heap.pop();\n  }\n  return heap.peek();\n}` },
      { id: 'top_k_frequent', name: 'Top K Frequent Elements', recurrence: 'Bucket sort / heap O(n log k)', complexity: 'O(n log k)', code: `function topKFrequent(nums, k) {\n  const freq = {};\n  for (const n of nums) freq[n] = (freq[n] || 0) + 1;\n  return Object.entries(freq)\n    .sort((a, b) => b[1] - a[1])\n    .slice(0, k)\n    .map(e => Number(e[0]));\n}` },
      { id: 'median_stream', name: 'Median in Data Stream', recurrence: 'Two heaps (maxHeap + minHeap)', complexity: 'O(log n) add', code: `class MedianFinder {\n  constructor() { this.lo = []; this.hi = []; }\n  addNum(num) {\n    this.lo.push(num);\n    this.lo.sort((a, b) => b - a);\n    this.hi.push(this.lo.shift());\n    this.hi.sort((a, b) => a - b);\n    if (this.hi.length > this.lo.length)\n      this.lo.push(this.hi.shift());\n  }\n  findMedian() {\n    if (this.lo.length > this.hi.length) return this.lo[0];\n    return (this.lo[0] + this.hi[0]) / 2;\n  }\n}` },
    ]
  },

  RECURSION: {
    id: 'RECURSION', name: 'Recursion', color: '#cf6679',
    algorithms: [
      { id: 'factorial', name: 'Factorial', recurrence: 'T(n) = T(n-1) + O(1)', complexity: 'O(n)', code: `function factorial(n) {\n  if (n <= 1) return 1;\n  return n * factorial(n - 1);\n}` },
      { id: 'fibonacci', name: 'Fibonacci', recurrence: 'T(n) = T(n-1) + T(n-2)', complexity: 'O(2^n) naive, O(n) memo', code: `function fibonacci(n, memo = {}) {\n  if (n <= 1) return n;\n  if (memo[n]) return memo[n];\n  return memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo);\n}` },
      { id: 'subsets', name: 'Subsets', recurrence: '2^n subsets, T(n)=2*T(n-1)', complexity: 'O(2^n)', code: `function subsets(nums) {\n  const result = [[]];\n  for (const num of nums) {\n    const newSubsets = result.map(s => [...s, num]);\n    result.push(...newSubsets);\n  }\n  return result;\n}` },
      { id: 'permutations', name: 'Permutations', recurrence: 'n! permutations', complexity: 'O(n!)', code: `function permutations(nums) {\n  const result = [];\n  function backtrack(current, remaining) {\n    if (!remaining.length) { result.push([...current]); return; }\n    for (let i = 0; i < remaining.length; i++) {\n      current.push(remaining[i]);\n      backtrack(current, remaining.filter((_, j) => j !== i));\n      current.pop();\n    }\n  }\n  backtrack([], nums);\n  return result;\n}` },
      { id: 'combination_sum', name: 'Combination Sum', recurrence: 'Recursive pick/skip with unlimited use', complexity: 'O(n^(t/m))', code: `function combinationSum(candidates, target) {\n  const result = [];\n  function dfs(start, current, remaining) {\n    if (remaining === 0) { result.push([...current]); return; }\n    for (let i = start; i < candidates.length; i++) {\n      if (candidates[i] <= remaining) {\n        current.push(candidates[i]);\n        dfs(i, current, remaining - candidates[i]);\n        current.pop();\n      }\n    }\n  }\n  dfs(0, [], target);\n  return result;\n}` },
      { id: 'generate_parens', name: 'Generate Parentheses', recurrence: 'Catalan number C(n) = C(2n,n)/(n+1)', complexity: 'O(4^n / √n)', code: `function generateParenthesis(n) {\n  const result = [];\n  function dfs(s, open, close) {\n    if (s.length === 2 * n) { result.push(s); return; }\n    if (open < n) dfs(s + '(', open + 1, close);\n    if (close < open) dfs(s + ')', open, close + 1);\n  }\n  dfs('', 0, 0);\n  return result;\n}` },
    ]
  },

  BACKTRACKING: {
    id: 'BACKTRACKING', name: 'Backtracking', color: '#ff6d00',
    algorithms: [
      { id: 'n_queens', name: 'N Queens', recurrence: 'Place queen row by row, check conflicts', complexity: 'O(n!)', code: `function solveNQueens(n) {\n  const result = [];\n  const board = Array.from({ length: n }, () => '.'.repeat(n).split(''));\n  function isValid(row, col) {\n    for (let i = 0; i < row; i++) if (board[i][col] === 'Q') return false;\n    for (let i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--)\n      if (board[i][j] === 'Q') return false;\n    for (let i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++)\n      if (board[i][j] === 'Q') return false;\n    return true;\n  }\n  function backtrack(row) {\n    if (row === n) { result.push(board.map(r => r.join(''))); return; }\n    for (let col = 0; col < n; col++) {\n      if (isValid(row, col)) {\n        board[row][col] = 'Q';\n        backtrack(row + 1);\n        board[row][col] = '.';\n      }\n    }\n  }\n  backtrack(0);\n  return result;\n}` },
      { id: 'sudoku', name: 'Sudoku Solver', recurrence: 'Fill empty cells 1-9 with validity check', complexity: 'O(9^m) m=empty cells', code: `function solveSudoku(board) {\n  function isValid(board, row, col, num) {\n    for (let i = 0; i < 9; i++) {\n      if (board[row][i] === num) return false;\n      if (board[i][col] === num) return false;\n      const r = 3 * Math.floor(row / 3) + Math.floor(i / 3);\n      const c = 3 * Math.floor(col / 3) + (i % 3);\n      if (board[r][c] === num) return false;\n    }\n    return true;\n  }\n  function solve(board) {\n    for (let i = 0; i < 9; i++) {\n      for (let j = 0; j < 9; j++) {\n        if (board[i][j] === '.') {\n          for (let d = 1; d <= 9; d++) {\n            const num = String(d);\n            if (isValid(board, i, j, num)) {\n              board[i][j] = num;\n              if (solve(board)) return true;\n              board[i][j] = '.';\n            }\n          }\n          return false;\n        }\n      }\n    }\n    return true;\n  }\n  solve(board);\n}` },
      { id: 'word_search', name: 'Word Search', recurrence: 'DFS + backtrack on grid', complexity: 'O(n*m*4^L)', code: `function exist(board, word) {\n  const rows = board.length, cols = board[0].length;\n  function dfs(r, c, i) {\n    if (i === word.length) return true;\n    if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] !== word[i]) return false;\n    const temp = board[r][c];\n    board[r][c] = '#';\n    const found = dfs(r+1,c,i+1)||dfs(r-1,c,i+1)||dfs(r,c+1,i+1)||dfs(r,c-1,i+1);\n    board[r][c] = temp;\n    return found;\n  }\n  for (let r = 0; r < rows; r++)\n    for (let c = 0; c < cols; c++)\n      if (dfs(r, c, 0)) return true;\n  return false;\n}` },
      { id: 'palindrome_partition', name: 'Palindrome Partitioning', recurrence: 'DFS partition + isPalin check', complexity: 'O(n * 2^n)', code: `function partition(s) {\n  const result = [];\n  function isPalin(str) { return str === str.split('').reverse().join(''); }\n  function dfs(start, path) {\n    if (start === s.length) { result.push([...path]); return; }\n    for (let end = start + 1; end <= s.length; end++) {\n      const sub = s.slice(start, end);\n      if (isPalin(sub)) {\n        path.push(sub);\n        dfs(end, path);\n        path.pop();\n      }\n    }\n  }\n  dfs(0, []);\n  return result;\n}` },
    ]
  },

  GREEDY: {
    id: 'GREEDY', name: 'Greedy Algorithms', color: '#ff00ff',
    algorithms: [
      { id: 'kruskal', name: 'Kruskal MST', recurrence: 'Greedy: sort edges + union-find O(E log E)', complexity: 'O(E log E)', code: `function kruskal(V, edges) {\n  edges.sort((a, b) => a[2] - b[2]);\n  const parent = Array.from({length: V}, (_, i) => i);\n  const find = x => parent[x] === x ? x : (parent[x] = find(parent[x]));\n  const union = (a, b) => { parent[find(a)] = find(b); };\n  const mst = [];\n  for (const [u, v, w] of edges) {\n    if (find(u) !== find(v)) { union(u, v); mst.push([u, v, w]); }\n  }\n  return mst;\n}` },
      { id: 'huffman', name: 'Huffman Coding', recurrence: 'Cost(Tree) = Σ f(c) * d(c)', complexity: 'O(n log n)', code: `function buildHuffmanTree(chars, freqs) {\n  const pq = chars.map((c, i) => ({ c, freq: freqs[i], left: null, right: null }));\n  pq.sort((a, b) => a.freq - b.freq);\n  while (pq.length > 1) {\n    pq.sort((a, b) => a.freq - b.freq);\n    const left = pq.shift();\n    const right = pq.shift();\n    pq.push({ c: null, freq: left.freq + right.freq, left, right });\n  }\n  return pq[0];\n}` },
      { id: 'activity_selection', name: 'Activity Selection', recurrence: 'Sort by end time, greedily pick', complexity: 'O(n log n)', code: `function activitySelection(activities) {\n  activities.sort((a, b) => a[1] - b[1]);\n  const selected = [activities[0]];\n  let lastEnd = activities[0][1];\n  for (let i = 1; i < activities.length; i++) {\n    if (activities[i][0] >= lastEnd) {\n      selected.push(activities[i]);\n      lastEnd = activities[i][1];\n    }\n  }\n  return selected;\n}` },
      { id: 'fractional_knapsack', name: 'Fractional Knapsack', recurrence: 'Sort by value/weight ratio', complexity: 'O(n log n)', code: `function fractionalKnapsack(capacity, items) {\n  items.sort((a, b) => b.value / b.weight - a.value / a.weight);\n  let totalValue = 0;\n  for (const item of items) {\n    if (capacity <= 0) break;\n    const take = Math.min(item.weight, capacity);\n    totalValue += take * (item.value / item.weight);\n    capacity -= take;\n  }\n  return totalValue;\n}` },
      { id: 'jump_game', name: 'Jump Game', recurrence: 'Track max reachable index', complexity: 'O(n)', code: `function canJump(nums) {\n  let maxReach = 0;\n  for (let i = 0; i < nums.length; i++) {\n    if (i > maxReach) return false;\n    maxReach = Math.max(maxReach, i + nums[i]);\n  }\n  return true;\n}` },
      { id: 'candy_distribution', name: 'Candy Distribution', recurrence: 'Two-pass greedy O(n)', complexity: 'O(n)', code: `function candy(ratings) {\n  const n = ratings.length;\n  const candies = new Array(n).fill(1);\n  for (let i = 1; i < n; i++)\n    if (ratings[i] > ratings[i-1]) candies[i] = candies[i-1] + 1;\n  for (let i = n - 2; i >= 0; i--)\n    if (ratings[i] > ratings[i+1]) candies[i] = Math.max(candies[i], candies[i+1] + 1);\n  return candies.reduce((a, b) => a + b, 0);\n}` },
    ]
  },

  DYNAMIC_PROGRAMMING: {
    id: 'DYNAMIC_PROGRAMMING', name: 'Dynamic Programming', color: '#ffcc00',
    algorithms: [
      { id: 'fib_dp', name: 'Fibonacci DP', recurrence: 'dp[i] = dp[i-1] + dp[i-2]', complexity: 'O(n)', code: `function fibDP(n) {\n  if (n <= 1) return n;\n  let a = 0, b = 1;\n  for (let i = 2; i <= n; i++) {\n    [a, b] = [b, a + b];\n  }\n  return b;\n}` },
      { id: 'climbing_stairs', name: 'Climbing Stairs', recurrence: 'dp[i] = dp[i-1] + dp[i-2]', complexity: 'O(n)', code: `function climbStairs(n) {\n  let a = 1, b = 1;\n  for (let i = 2; i <= n; i++) {\n    [a, b] = [b, a + b];\n  }\n  return b;\n}` },
      { id: 'knapsack_01', name: '0/1 Knapsack', recurrence: 'dp[i][w] = max(dp[i-1][w], dp[i-1][w-wt[i]]+val[i])', complexity: 'O(n*W)', code: `function knapsack(weights, values, W) {\n  const n = weights.length;\n  const dp = Array.from({length: n+1}, () => new Array(W+1).fill(0));\n  for (let i = 1; i <= n; i++) {\n    for (let w = 0; w <= W; w++) {\n      dp[i][w] = dp[i-1][w];\n      if (weights[i-1] <= w)\n        dp[i][w] = Math.max(dp[i][w], dp[i-1][w-weights[i-1]] + values[i-1]);\n    }\n  }\n  return dp[n][W];\n}` },
      { id: 'coin_change', name: 'Coin Change', recurrence: 'dp[i] = min(dp[i], dp[i-coin]+1)', complexity: 'O(n*amount)', code: `function coinChange(coins, amount) {\n  const dp = new Array(amount + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let i = 1; i <= amount; i++) {\n    for (const coin of coins) {\n      if (coin <= i) dp[i] = Math.min(dp[i], dp[i - coin] + 1);\n    }\n  }\n  return dp[amount] === Infinity ? -1 : dp[amount];\n}` },
      { id: 'lcs', name: 'Longest Common Subsequence', recurrence: 'L[i][j] = L[i-1][j-1]+1 if match, else max(L[i-1][j], L[i][j-1])', complexity: 'O(m*n)', code: `function LCS(X, Y) {\n  const m = X.length, n = Y.length;\n  const L = Array.from({length: m+1}, () => new Array(n+1).fill(0));\n  for (let i = 1; i <= m; i++)\n    for (let j = 1; j <= n; j++)\n      L[i][j] = X[i-1]===Y[j-1] ? L[i-1][j-1]+1 : Math.max(L[i-1][j], L[i][j-1]);\n  return L[m][n];\n}` },
      { id: 'lis', name: 'Longest Increasing Subsequence', recurrence: 'dp[i] = max(dp[j])+1 for j<i and arr[j]<arr[i]', complexity: 'O(n log n)', code: `function lengthOfLIS(nums) {\n  const tails = [];\n  for (const num of nums) {\n    let lo = 0, hi = tails.length;\n    while (lo < hi) {\n      const mid = (lo + hi) >> 1;\n      if (tails[mid] < num) lo = mid + 1;\n      else hi = mid;\n    }\n    tails[lo] = num;\n  }\n  return tails.length;\n}` },
      { id: 'edit_distance', name: 'Edit Distance', recurrence: 'dp[i][j] = min ops to convert s1[0..i] to s2[0..j]', complexity: 'O(m*n)', code: `function minDistance(word1, word2) {\n  const m = word1.length, n = word2.length;\n  const dp = Array.from({length: m+1}, (_, i) => Array.from({length: n+1}, (_, j) => i || j));\n  for (let i = 1; i <= m; i++)\n    for (let j = 1; j <= n; j++)\n      dp[i][j] = word1[i-1]===word2[j-1] ? dp[i-1][j-1]\n        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);\n  return dp[m][n];\n}` },
      { id: 'matrix_chain', name: 'Matrix Chain Multiplication', recurrence: 'm[i,j] = min_k(m[i,k]+m[k+1,j]+p[i-1]*p[k]*p[j])', complexity: 'O(n³)', code: `function matrixChainOrder(p) {\n  const n = p.length - 1;\n  const m = Array.from({length: n+1}, () => new Array(n+1).fill(0));\n  for (let l = 2; l <= n; l++)\n    for (let i = 1; i <= n-l+1; i++) {\n      const j = i+l-1;\n      m[i][j] = Infinity;\n      for (let k = i; k < j; k++)\n        m[i][j] = Math.min(m[i][j], m[i][k]+m[k+1][j]+p[i-1]*p[k]*p[j]);\n    }\n  return m[1][n];\n}` },
      { id: 'house_robber', name: 'House Robber', recurrence: 'dp[i] = max(dp[i-1], dp[i-2]+nums[i])', complexity: 'O(n)', code: `function rob(nums) {\n  let prev2 = 0, prev1 = 0;\n  for (const num of nums) {\n    const curr = Math.max(prev1, prev2 + num);\n    prev2 = prev1;\n    prev1 = curr;\n  }\n  return prev1;\n}` },
      { id: 'subset_sum', name: 'Partition Equal Subset Sum', recurrence: 'dp[j] = dp[j] || dp[j-num]', complexity: 'O(n*sum)', code: `function canPartition(nums) {\n  const sum = nums.reduce((a, b) => a + b, 0);\n  if (sum % 2 !== 0) return false;\n  const target = sum / 2;\n  const dp = new Array(target + 1).fill(false);\n  dp[0] = true;\n  for (const num of nums)\n    for (let j = target; j >= num; j--)\n      dp[j] = dp[j] || dp[j - num];\n  return dp[target];\n}` },
    ]
  },

  GRAPHS: {
    id: 'GRAPHS', name: 'Graphs', color: '#18ffff',
    algorithms: [
      { id: 'graph_dfs', name: 'DFS', recurrence: 'O(V + E)', complexity: 'O(V + E)', code: `function dfs(graph, start) {\n  const visited = new Set();\n  function explore(node) {\n    if (visited.has(node)) return;\n    visited.add(node);\n    console.log(node);\n    for (const neighbor of (graph[node] || [])) explore(neighbor);\n  }\n  explore(start);\n}` },
      { id: 'graph_bfs', name: 'BFS', recurrence: 'O(V + E)', complexity: 'O(V + E)', code: `function bfs(graph, start) {\n  const visited = new Set([start]);\n  const queue = [start];\n  while (queue.length) {\n    const node = queue.shift();\n    console.log(node);\n    for (const neighbor of (graph[node] || [])) {\n      if (!visited.has(neighbor)) {\n        visited.add(neighbor);\n        queue.push(neighbor);\n      }\n    }\n  }\n}` },
      { id: 'topological_sort', name: 'Topological Sort', recurrence: 'Kahn\'s BFS + in-degree', complexity: 'O(V + E)', code: `function topoSort(V, adj) {\n  const inDegree = new Array(V).fill(0);\n  for (const [u, v] of adj) inDegree[v]++;\n  const queue = [];\n  for (let i = 0; i < V; i++) if (inDegree[i] === 0) queue.push(i);\n  const result = [];\n  while (queue.length) {\n    const node = queue.shift();\n    result.push(node);\n    for (const [u, v] of adj)\n      if (u === node && --inDegree[v] === 0) queue.push(v);\n  }\n  return result.length === V ? result : [];\n}` },
      { id: 'dijkstra', name: "Dijkstra's Algorithm", recurrence: 'Relax edges greedily, O((V+E) log V)', complexity: 'O((V + E) log V)', code: `function dijkstra(graph, src) {\n  const dist = {};\n  const visited = new Set();\n  for (const node in graph) dist[node] = Infinity;\n  dist[src] = 0;\n  // Min-priority queue (simplified)\n  const pq = [[0, src]];\n  while (pq.length) {\n    pq.sort((a, b) => a[0] - b[0]);\n    const [d, u] = pq.shift();\n    if (visited.has(u)) continue;\n    visited.add(u);\n    for (const [v, w] of (graph[u] || [])) {\n      if (dist[u] + w < dist[v]) {\n        dist[v] = dist[u] + w;\n        pq.push([dist[v], v]);\n      }\n    }\n  }\n  return dist;\n}` },
      { id: 'bellman_ford', name: 'Bellman-Ford', recurrence: 'Relax all edges V-1 times', complexity: 'O(V * E)', code: `function bellmanFord(V, edges, src) {\n  const dist = new Array(V).fill(Infinity);\n  dist[src] = 0;\n  for (let i = 0; i < V - 1; i++) {\n    for (const [u, v, w] of edges) {\n      if (dist[u] !== Infinity && dist[u] + w < dist[v])\n        dist[v] = dist[u] + w;\n    }\n  }\n  // Negative cycle check\n  for (const [u, v, w] of edges)\n    if (dist[u] !== Infinity && dist[u] + w < dist[v])\n      return null; // negative cycle\n  return dist;\n}` },
      { id: 'floyd_warshall', name: 'Floyd-Warshall', recurrence: 'dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j])', complexity: 'O(V³)', code: `function floydWarshall(dist, V) {\n  for (let k = 0; k < V; k++)\n    for (let i = 0; i < V; i++)\n      for (let j = 0; j < V; j++)\n        if (dist[i][k] + dist[k][j] < dist[i][j])\n          dist[i][j] = dist[i][k] + dist[k][j];\n  return dist;\n}` },
      { id: 'prim', name: "Prim's Algorithm", recurrence: 'Greedy: always pick min edge to unvisited', complexity: 'O(E log V)', code: `function prim(V, adj) {\n  const key = new Array(V).fill(Infinity);\n  const inMST = new Array(V).fill(false);\n  key[0] = 0;\n  let mstWeight = 0;\n  for (let i = 0; i < V; i++) {\n    // Pick min key vertex not in MST\n    let u = -1;\n    for (let v = 0; v < V; v++)\n      if (!inMST[v] && (u === -1 || key[v] < key[u])) u = v;\n    inMST[u] = true;\n    mstWeight += key[u];\n    for (const [v, w] of (adj[u] || []))\n      if (!inMST[v] && w < key[v]) key[v] = w;\n  }\n  return mstWeight;\n}` },
      { id: 'dsu', name: 'DSU / Union Find', recurrence: 'Near O(1) with path compression + union by rank', complexity: 'O(α(n)) per op', code: `class DSU {\n  constructor(n) {\n    this.parent = Array.from({length: n}, (_, i) => i);\n    this.rank = new Array(n).fill(0);\n  }\n  find(x) {\n    if (this.parent[x] !== x)\n      this.parent[x] = this.find(this.parent[x]);\n    return this.parent[x];\n  }\n  union(a, b) {\n    const ra = this.find(a), rb = this.find(b);\n    if (ra === rb) return false;\n    if (this.rank[ra] < this.rank[rb]) this.parent[ra] = rb;\n    else if (this.rank[ra] > this.rank[rb]) this.parent[rb] = ra;\n    else { this.parent[rb] = ra; this.rank[ra]++; }\n    return true;\n  }\n}` },
      { id: 'bipartite_check', name: 'Bipartite Graph Check', recurrence: '2-coloring via BFS/DFS', complexity: 'O(V + E)', code: `function isBipartite(graph) {\n  const color = new Array(graph.length).fill(-1);\n  for (let start = 0; start < graph.length; start++) {\n    if (color[start] !== -1) continue;\n    const queue = [start];\n    color[start] = 0;\n    while (queue.length) {\n      const node = queue.shift();\n      for (const neighbor of graph[node]) {\n        if (color[neighbor] === -1) {\n          color[neighbor] = 1 - color[node];\n          queue.push(neighbor);\n        } else if (color[neighbor] === color[node]) return false;\n      }\n    }\n  }\n  return true;\n}` },
    ]
  },

  BIT_MANIPULATION: {
    id: 'BIT_MANIPULATION', name: 'Bit Manipulation', color: '#b9f6ca',
    algorithms: [
      { id: 'xor_tricks', name: 'XOR Tricks', recurrence: 'a^a=0, a^0=a', complexity: 'O(n)', code: `// Find single non-duplicate element\nfunction singleNumber(nums) {\n  return nums.reduce((xor, n) => xor ^ n, 0);\n}\n\n// Swap without temp\nfunction swap(a, b) {\n  a ^= b; b ^= a; a ^= b;\n  return [a, b];\n}\n\n// Find two non-duplicates\nfunction singleNumberIII(nums) {\n  let xor = nums.reduce((x, n) => x ^ n, 0);\n  const bit = xor & (-xor);\n  let a = 0, b = 0;\n  for (const n of nums) {\n    if (n & bit) a ^= n;\n    else b ^= n;\n  }\n  return [a, b];\n}` },
      { id: 'power_of_two', name: 'Power of Two Check', recurrence: 'n & (n-1) == 0', complexity: 'O(1)', code: `function isPowerOfTwo(n) {\n  return n > 0 && (n & (n - 1)) === 0;\n}\n\n// Power of Four\nfunction isPowerOfFour(n) {\n  return n > 0 && (n & (n-1)) === 0 && (n & 0xAAAAAAAA) === 0;\n}` },
      { id: 'count_set_bits', name: 'Count Set Bits', recurrence: 'Brian Kernighan: n & (n-1) strips lowest bit', complexity: 'O(set bits)', code: `// Brian Kernighan's Algorithm\nfunction countBits(n) {\n  let count = 0;\n  while (n) { n &= n - 1; count++; }\n  return count;\n}\n\n// For range [0, n]\nfunction countBitsRange(n) {\n  const dp = new Array(n + 1).fill(0);\n  for (let i = 1; i <= n; i++)\n    dp[i] = dp[i >> 1] + (i & 1);\n  return dp;\n}` },
      { id: 'subsets_bitmask', name: 'Subsets using Bitmasking', recurrence: '2^n subsets via bitmask', complexity: 'O(n * 2^n)', code: `function subsetsWithBitmask(nums) {\n  const n = nums.length;\n  const result = [];\n  for (let mask = 0; mask < (1 << n); mask++) {\n    const subset = [];\n    for (let i = 0; i < n; i++) {\n      if (mask & (1 << i)) subset.push(nums[i]);\n    }\n    result.push(subset);\n  }\n  return result;\n}` },
    ]
  },

  MATHEMATICAL: {
    id: 'MATHEMATICAL', name: 'Mathematical Algorithms', color: '#ffab40',
    algorithms: [
      { id: 'sieve', name: 'Sieve of Eratosthenes', recurrence: 'Mark composites O(n log log n)', complexity: 'O(n log log n)', code: `function sieve(n) {\n  const is_prime = new Array(n + 1).fill(true);\n  is_prime[0] = is_prime[1] = false;\n  for (let i = 2; i * i <= n; i++) {\n    if (is_prime[i]) {\n      for (let j = i * i; j <= n; j += i)\n        is_prime[j] = false;\n    }\n  }\n  return is_prime.reduce((p, v, i) => v ? [...p, i] : p, []);\n}` },
      { id: 'gcd_euclid', name: 'GCD / Euclid Algorithm', recurrence: 'gcd(a,b) = gcd(b, a%b)', complexity: 'O(log min(a,b))', code: `function gcd(a, b) {\n  while (b) { [a, b] = [b, a % b]; }\n  return a;\n}\n\nfunction lcm(a, b) {\n  return (a / gcd(a, b)) * b;\n}` },
      { id: 'fast_expo', name: 'Fast Exponentiation', recurrence: 'T(n) = T(n/2) + O(1)', complexity: 'O(log n)', code: `function fastPow(base, exp, mod = 1e9 + 7) {\n  let result = 1;\n  base %= mod;\n  while (exp > 0) {\n    if (exp & 1) result = (result * base) % mod;\n    base = (base * base) % mod;\n    exp >>= 1;\n  }\n  return result;\n}` },
      { id: 'prime_factorization', name: 'Prime Factorization', recurrence: 'Trial division up to √n', complexity: 'O(√n)', code: `function primeFactors(n) {\n  const factors = [];\n  for (let i = 2; i * i <= n; i++) {\n    while (n % i === 0) {\n      factors.push(i);\n      n /= i;\n    }\n  }\n  if (n > 1) factors.push(n);\n  return factors;\n}` },
      { id: 'modular_arithmetic', name: 'Modular Arithmetic', recurrence: '(a + b) % m = ((a % m) + (b % m)) % m', complexity: 'O(log n)', code: `const MOD = 1e9 + 7;\n\nfunction modAdd(a, b) { return (a + b) % MOD; }\nfunction modMul(a, b) { return (a * b) % MOD; }\nfunction modPow(base, exp) {\n  let result = 1; base %= MOD;\n  while (exp > 0) {\n    if (exp & 1) result = modMul(result, base);\n    base = modMul(base, base); exp >>= 1;\n  }\n  return result;\n}\nfunction modInverse(a) { return modPow(a, MOD - 2); }` },
    ]
  },

  ADVANCED_DSA: {
    id: 'ADVANCED_DSA', name: 'Advanced DSA', color: '#ff6e40',
    algorithms: [
      { id: 'trie', name: 'Trie', recurrence: 'Insert/Search O(m) m=word length', complexity: 'O(m)', code: `class TrieNode {\n  constructor() { this.children = {}; this.isEnd = false; }\n}\n\nclass Trie {\n  constructor() { this.root = new TrieNode(); }\n  insert(word) {\n    let node = this.root;\n    for (const c of word) {\n      if (!node.children[c]) node.children[c] = new TrieNode();\n      node = node.children[c];\n    }\n    node.isEnd = true;\n  }\n  search(word) {\n    let node = this.root;\n    for (const c of word) {\n      if (!node.children[c]) return false;\n      node = node.children[c];\n    }\n    return node.isEnd;\n  }\n}` },
      { id: 'segment_tree', name: 'Segment Tree', recurrence: 'Build O(n), Query/Update O(log n)', complexity: 'O(log n) query', code: `class SegmentTree {\n  constructor(arr) {\n    this.n = arr.length;\n    this.tree = new Array(4 * this.n).fill(0);\n    this.build(arr, 0, 0, this.n - 1);\n  }\n  build(arr, node, start, end) {\n    if (start === end) { this.tree[node] = arr[start]; return; }\n    const mid = (start + end) >> 1;\n    this.build(arr, 2*node+1, start, mid);\n    this.build(arr, 2*node+2, mid+1, end);\n    this.tree[node] = this.tree[2*node+1] + this.tree[2*node+2];\n  }\n  query(node, start, end, l, r) {\n    if (r < start || end < l) return 0;\n    if (l <= start && end <= r) return this.tree[node];\n    const mid = (start + end) >> 1;\n    return this.query(2*node+1, start, mid, l, r) +\n           this.query(2*node+2, mid+1, end, l, r);\n  }\n}` },
      { id: 'fenwick_tree', name: 'Fenwick Tree (BIT)', recurrence: 'Update/Query O(log n) using LSB', complexity: 'O(log n)', code: `class FenwickTree {\n  constructor(n) { this.tree = new Array(n + 1).fill(0); this.n = n; }\n  update(i, delta) {\n    for (; i <= this.n; i += i & (-i))\n      this.tree[i] += delta;\n  }\n  query(i) {\n    let sum = 0;\n    for (; i > 0; i -= i & (-i))\n      sum += this.tree[i];\n    return sum;\n  }\n  rangeQuery(l, r) { return this.query(r) - this.query(l - 1); }\n}` },
      { id: 'sparse_table', name: 'Sparse Table', recurrence: 'Build O(n log n), RMQ O(1)', complexity: 'O(1) query', code: `function buildSparseTable(arr) {\n  const n = arr.length;\n  const LOG = Math.floor(Math.log2(n)) + 1;\n  const table = Array.from({length: LOG}, () => new Array(n));\n  table[0] = [...arr];\n  for (let j = 1; j < LOG; j++)\n    for (let i = 0; i + (1 << j) <= n; i++)\n      table[j][i] = Math.min(table[j-1][i], table[j-1][i + (1 << (j-1))]);\n  return table;\n}\n\nfunction rmq(table, l, r) {\n  const k = Math.floor(Math.log2(r - l + 1));\n  return Math.min(table[k][l], table[k][r - (1 << k) + 1]);\n}` },
      { id: 'rolling_hash', name: 'Rolling Hash', recurrence: 'hash(s[i..j]) computed in O(1) after O(n) build', complexity: 'O(n) build, O(1) query', code: `function rollingHash(s, base = 31, mod = 1e9 + 7) {\n  const n = s.length;\n  const h = new Array(n + 1).fill(0);\n  const pw = new Array(n + 1).fill(1);\n  for (let i = 0; i < n; i++) {\n    h[i+1] = (h[i] * base + s.charCodeAt(i)) % mod;\n    pw[i+1] = (pw[i] * base) % mod;\n  }\n  const getHash = (l, r) => (h[r+1] - h[l] * pw[r-l+1] % mod + mod) % mod;\n  return { getHash };\n}` },
    ]
  },

  DIVIDE_CONQUER: {
    id: 'DIVIDE_CONQUER', name: 'Divide & Conquer', color: '#00ffff',
    algorithms: [
      { id: 'merge_sort_dc', name: 'Merge Sort', recurrence: 'T(n) = 2T(n/2) + O(n)', complexity: 'O(n log n)', code: `function mergeSort(arr) {\n  if (arr.length <= 1) return arr;\n  const mid = arr.length >> 1;\n  const left = mergeSort(arr.slice(0, mid));\n  const right = mergeSort(arr.slice(mid));\n  return merge(left, right);\n}\n\nfunction merge(l, r) {\n  const res = [];\n  let i = 0, j = 0;\n  while (i < l.length && j < r.length) {\n    if (l[i] <= r[j]) res.push(l[i++]);\n    else res.push(r[j++]);\n  }\n  return res.concat(l.slice(i), r.slice(j));\n}` },
      { id: 'quick_sort_dc', name: 'Quick Sort', recurrence: 'Avg: T(n)=2T(n/2)+O(n)', complexity: 'O(n log n)', code: `function quickSort(arr, lo = 0, hi = arr.length - 1) {\n  if (lo < hi) {\n    const p = partition(arr, lo, hi);\n    quickSort(arr, lo, p - 1);\n    quickSort(arr, p + 1, hi);\n  }\n  return arr;\n}\n\nfunction partition(arr, lo, hi) {\n  const pivot = arr[hi];\n  let i = lo - 1;\n  for (let j = lo; j < hi; j++) {\n    if (arr[j] <= pivot) { i++; [arr[i], arr[j]] = [arr[j], arr[i]]; }\n  }\n  [arr[i+1], arr[hi]] = [arr[hi], arr[i+1]];\n  return i + 1;\n}` },
      { id: 'binary_search_dc', name: 'Binary Search', recurrence: 'T(n) = T(n/2) + O(1)', complexity: 'O(log n)', code: `function binarySearch(arr, target) {\n  let left = 0, right = arr.length - 1;\n  while (left <= right) {\n    const mid = (left + right) >> 1;\n    if (arr[mid] === target) return mid;\n    if (arr[mid] < target) left = mid + 1;\n    else right = mid - 1;\n  }\n  return -1;\n}` },
      { id: 'strassen', name: "Strassen's Matrix Multiplication", recurrence: 'T(n) = 7T(n/2) + O(n²)', complexity: 'O(n^2.81)', code: `// Strassen's algorithm for 2x2 demonstration\nfunction strassen2x2(A, B) {\n  const m1 = (A[0][0] + A[1][1]) * (B[0][0] + B[1][1]);\n  const m2 = (A[1][0] + A[1][1]) * B[0][0];\n  const m3 = A[0][0] * (B[0][1] - B[1][1]);\n  const m4 = A[1][1] * (B[1][0] - B[0][0]);\n  const m5 = (A[0][0] + A[0][1]) * B[1][1];\n  const m6 = (A[1][0] - A[0][0]) * (B[0][0] + B[0][1]);\n  const m7 = (A[0][1] - A[1][1]) * (B[1][0] + B[1][1]);\n  return [\n    [m1+m4-m5+m7, m3+m5],\n    [m2+m4, m1-m2+m3+m6]\n  ];\n}` },
    ]
  },
};
